INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Leistungsportfolio immer nur Dienstleistungen umfasst. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Produkte enthalten"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich ein Leistungsportfolio für ein IT-Unternehmen erstelle?', 3, '[{"text": "Kundenanforderungen", "correct": true, "because": "Steuert Angebot"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Qualität zählt"}, {"text": "Farbliches Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören typischerweise zu einem IT-Leistungsportfolio?', 5, '[{"text": "Support-Dienste", "correct": true, "because": "Wichtig für Kunden"}, {"text": "Hardwarelösungen", "correct": true, "because": "Teil des Angebots"}, {"text": "Bürogestaltung", "correct": false, "because": "Kein IT-Fokus"}, {"text": "Werbestrategien", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Leistungsportfolio zeigt die Kompetenzen eines Unternehmens. b) Es ist immer auf Hardware beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht nur Hardware"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Leistungsportfolio für IT-Kunden erstelle?', 4, '[{"text": "Marktbedarf", "correct": false, "because": "Bestimmt Relevanz"}, {"text": "Dienstleistungsumfang", "correct": false, "because": "Kern des Portfolios"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Portfoliofaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Leistungsportfolio nur für große Firmen wichtig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMU brauchen Übersicht"}, {"text": "Ja", "correct": false, "because": "Für alle relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einem Leistungsportfolio in der IT?', 3, '[{"text": "Kundeninformation", "correct": true, "because": "Zeigt Angebot"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direktes Ziel"}, {"text": "Weniger Dienstleistungen", "correct": false, "because": "Nicht erwünscht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bestandteile machen ein IT-Leistungsportfolio umfassend?', 5, '[{"text": "Softwareentwicklung", "correct": true, "because": "Häufig angeboten"}, {"text": "Netzwerkdienste", "correct": true, "because": "Wichtiger Bereich"}, {"text": "Büromöbel", "correct": false, "because": "Kein IT-Bereich"}, {"text": "Werbekampagnen", "correct": false, "because": "Nicht zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Ein Leistungsportfolio hilft bei der Kundenakquise. b) Es enthält nur Produkte. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Dienstleistungen enthalten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für ein IT-Leistungsportfolio?', 4, '[{"text": "Dienstleistungsbeschreibung", "correct": false, "because": "Kernbestandteil"}, {"text": "Produktübersicht", "correct": false, "because": "Wichtiger Teil"}, {"text": "Büroplanung", "correct": true, "because": "Kein Portfoliofaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Leistungsportfolio immer statisch?', 2, '[{"text": "Nein", "correct": true, "because": "Passt sich Markt an"}, {"text": "Ja", "correct": false, "because": "Dynamisch anpassbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein umfassendes Leistungsportfolio?', 4, '[{"text": "Breitere Kundenbasis", "correct": true, "because": "Spricht mehr an"}, {"text": "Klare Positionierung", "correct": true, "because": "Zeigt Kompetenz"}, {"text": "Schnellere Lieferung", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Leistungsportfolio nur für interne Zwecke ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Kunden relevant"}, {"text": "Ja", "correct": false, "because": "Extern genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um ein Leistungsportfolio für IT-Dienstleistungen zu erstellen?', 3, '[{"text": "Kundenanalyse", "correct": true, "because": "Passt Angebot an"}, {"text": "Einheitliches Design", "correct": false, "because": "Sekundär"}, {"text": "Zufallsauswahl", "correct": false, "because": "Ungenau"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Leistungsportfolio kann Dienstleistungen und Produkte umfassen. b) Es ist immer auf Software beschränkt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nicht nur Software"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte berücksichtige ich bei einem IT-Leistungsportfolio?', 5, '[{"text": "Marktnachfrage", "correct": true, "because": "Bestimmt Relevanz"}, {"text": "Kompetenzbereiche", "correct": true, "because": "Zeigt Stärken"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich ein Leistungsportfolio für IT erstelle?', 3, '[{"text": "Dienstleistungsvielfalt", "correct": false, "because": "Wichtig für Breite"}, {"text": "Kundennutzen", "correct": false, "because": "Kern des Angebots"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Portfoliofaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss ein Leistungsportfolio nur Hardware enthalten?', 3, '[{"text": "Nein", "correct": true, "because": "Auch Dienstleistungen möglich"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Leistungsportfolio regelmäßig aktualisiert wird?', 2, '[{"text": "Ja", "correct": true, "because": "Passt sich Markt an"}, {"text": "Nein", "correct": false, "because": "Sollte dynamisch sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für ein IT-Leistungsportfolio?', 4, '[{"text": "Kundenspezifische Lösungen", "correct": true, "because": "Erfüllt Bedarf"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Qualität zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]');
